css:
.d1122-wheel,.d1122-star,.d1122-car{transform-box:fill-box;transform-origin:center}
.d1122-wheel{animation:d1122-w 3.6s ease-in-out infinite}
.d1122-star{animation:d1122-s 3.6s ease-in-out infinite}
.d1122-car{animation:d1122-c 3.6s ease-in-out infinite}
@keyframes d1122-w{0%,100%{transform:rotate(-18deg)}50%{transform:rotate(18deg)}}
@keyframes d1122-s{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
@keyframes d1122-c{0%{transform:translateX(0)}50%{transform:translateX(150px) translateY(8px)}60%{transform:translateX(140px)}100%{transform:translateX(0)}}
@media (prefers-reduced-motion:reduce){.d1122-wheel{transform:rotate(0)}.d1122-car{transform:translateX(60px)}}
